// 情绪极性：只区分「难受的事」和「其它」两档，够用就停。
//
// 为什么需要：回忆只看相关度时，一句「今天好累」可能把上周分手那段又翻出来。
// 证据方向一致——重提痛苦细节不会让人好受（Hallford & Mellor 的随机对照里，
// 重述难受细节那组和对照组没有差异），苦味重提和焦虑正相关（Korte n=171）。
// 所以负面记录不是不记，而是**短时间内不主动重提第二次**。
//
// 不做的事：不做细粒度情绪分类、不推断用户心理、不调模型。命中就标，标不准也只是少提一次。

import { userPartOf } from './text.js'

const NEG_RE = /(难过|伤心|想哭|哭了|崩溃|吵架|吵了|冷战|分手|离婚|去世|走了|过世|住院|生病|发烧|难受|疼|抑郁|焦虑|被骂|挨骂|失业|被裁|辞退|挂科|失败|失恋|倒霉|烦死|累死|气死|委屈|孤独|好累|太累|心累|好烦|心烦|郁闷|不开心|低落|撑不住|熬不住)/

export function toneOf(text) {
  return NEG_RE.test(userPartOf(text)) ? 'neg' : ''
}

// 同一条负面记录 48 小时内只提一次：第一次是她确实记得，第二次就是揭伤疤。
export const NEG_REMENTION_MS = 48 * 60 * 60 * 1000
